-- FitFirst starter nutrition seed. Values are curated estimates, not lab measurements.
-- Generated from the 50-item starter list in api/foods/search.js.
on conflict (source,source_id) do update set name=excluded.name, category=excluded.category, basis=excluded.basis, basis_grams=excluded.basis_grams, kcal=excluded.kcal, protein_g=excluded.protein_g, carbs_g=excluded.carbs_g, fat_g=excluded.fat_g, fiber_g=excluded.fiber_g, sugar_g=excluded.sugar_g, sodium_mg=excluded.sodium_mg, confidence=excluded.confidence, updated_at=now();